```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();
const mockOnComplete = vi.fn();
const mockOnCancel = vi.fn();

const defaultCartItems = [
  { id: '1', name: 'Elven Cloak', price: 99.99 },
  { id: '2', name: 'Mithril Shirt', price: 299.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: defaultCartItems,
    total: 399.98,
    clearCart: mockClearCart
  })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

const renderCheckout = () => render(
  <Checkout onComplete={mockOnComplete} onCancel={mockOnCancel} />
);

describe('Checkout - Happy Path', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    renderCheckout();

    // Arrange & Act - Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Rivendell Way');
    await user.type(screen.getByLabelText(/city/i), 'Gondor');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Assert - Payment step visible
    expect(screen.getByRole('heading', { name: /payment details/i })).toBeInTheDocument();

    // Act - Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Aragorn Elessar');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Assert - Review step
    expect(screen.getByRole('heading', { name: /review your order/i })).toBeInTheDocument();
    expect(screen.getByText(/card ending in 1111/i)).toBeInTheDocument();

    // Act - Place order
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Assert - Confirmation
    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText('ORD-12345')).toBeInTheDocument();
    });
    expect(mockClearCart).toHaveBeenCalled();
    expect(mockOnComplete).toHaveBeenCalledWith('ORD-12345');
  });
});

describe('Checkout - Form Validation', () => {
  it('displays error when ZIP code format is invalid', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code required/i);
    expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
  });
});

describe('Checkout - Error States', () => {
  it('displays payment error and allows retry', async () => {
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
    const user = userEvent.setup();
    // ... navigate to review step, click place order

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
    renderCheckout();

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });
});
